/*
	Theme of "Red" // 2.6.2023
	#minacoding #p5js #generativeart
	issue: screen not getting complete white over time
 */

let r, t = 0;
let cells = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(60);
	r = max(width, height) * 0.3
	colorMode(HSB, 100);
	background(255);
}

function draw() {
	background(255, 4); // why there is no complete white after some time
	translate(width*0.5, height*0.5);

	for (let i = floor(random(1,3)); i--;) {
		t = random(TWO_PI); // uncomment for angular order
		let x = 16 * sin(t) * sin(t) * sin(t);
		let y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t)
		x *= r / 16
		y *= r / -16
		y -= height * 0.15;
		const dev = 6;
		x += random(-dev, dev)
		y += random(-dev, dev)
		// point(x, y);
		cells.push(new Blood(x, y));
		// t += 0.05; // aww above, at random position
	}

	for (let i = cells.length - 1; i >= 0; i--) {
		b = cells[i]
		b.update()
		b.show()
		if (b.lifespan < 0) cells.splice(i, 1);
	}
}

function windowResized() {
	setup();
}
function mouseDragged() {
	cells.push(new Blood((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2));
}

class Blood {
	constructor(x, y) {
		this.x = x
		this.y = y
		this.d = 10
		this.c_h = random(98, 102) % 100;
		this.c_s = random(75, 100);
		this.c_b = random(50, 75);
		this.lifespan = 255;
		this.liferate = random(0.75, 4)
	}

	update() {
		this.lifespan-=this.liferate;
		this.d = map(this.lifespan, 255, 0, 10, 0.5)
		if (random() < 0.1) this.x += random(-this.d, this.d)
		this.y++
	}

	show() {
		push()
		stroke(this.c_h, this.c_s, this.c_b, this.lifespan)
		strokeWeight(this.d);
		point(this.x, this.y);
		pop();
	}
}
